source("h.R")
d <- html_parse("<!DOCTYPE html><html><head><title>T</title></head><body><div id=a class=' x  y\tx ' data-n=7 DATA-N=8 title=''><p CLASS=Big>one <b>bold</b></p><!--c--> tail<svg viewBox='0 0 1 1'><a xlink:href='#q'/></svg><template><p>tpl</p></template></div><input disabled></body></html>")
div <- html_element(d, "div"); all <- html_children(div, elements_only = FALSE); mix <- c(div, div[NA_integer_], all)
p("mix", mix)
p("name", html_name(mix)); p("type", html_type(mix)); p("ns", html_namespace(mix))
p("doc name/type/ns", list(html_name(d), html_type(d), html_namespace(d), html_text(d), html_attr(d, "x"), html_attrs(d), html_classes(d), html_strings(d)))
p("attr", html_attr(mix, "class")); p("attr default", html_attr(mix, "class", default = "D")); p("attr default NA", html_attr(mix, "class", default = NA))
for (dv in list(NA_character_, NA_integer_, NA_real_, 1, TRUE, NULL, c("a","b"), character(0), factor("a"), list("a"), "", "é")) { cat("default", deparse(dv)[1], ": "); print(tr(html_attr(mix[1:2], "nope", default = dv))) }
for (nv in list("CLASS", "data-n", "DATA-N", "viewbox", "viewBox", "xlink:href", "href", " class", "class ", "", NA_character_, c("id","class"), 1, NULL, factor("id"), c(n = "id"))) { cat("name", deparse(nv)[1], ": "); print(tr(html_attr(html_elements(d, "div, svg, svg a"), nv))) }
p("attrs", html_attrs(mix)); p("classes", html_classes(mix))
p("classes nbsp", html_classes(html_element(html_parse("<p class='a&nbsp;b &#x3000;c'>"), "p")))
p("text", html_text(mix)); p("text nonrec", html_text(mix, recursive = FALSE)); p("clean", html_text_clean(mix)); p("strings", html_strings(mix)); p("strings trim/drop", html_strings(mix, trim = TRUE, drop_empty = TRUE))
p("strings vs text", identical(vapply(html_strings(div), paste, "", collapse = ""), html_text(div)))
p("flags", list(tr(html_text(div, recursive = NA)), tr(html_text(div, 1)), tr(html_text_clean(div, trim = "a")), tr(html_text_clean(div, nbsp = c(TRUE,FALSE))), tr(html_strings(div, trim = NULL)), tr(html_strings(div, drop_empty = NA)), tr(html_children(div, elements_only = 0)), tr(html_serialize(div, outer = NA)), tr(html_serialize(div, pretty = "x"))))
p("children", html_children(mix)); p("children all", html_children(mix, FALSE)); p("parent", html_parent(mix)); p("ancestors", html_ancestors(html_element(d, "b"))); p("next", html_next_sibling(mix)); p("next any", html_next_sibling(mix, FALSE)); p("prev", html_previous_sibling(mix)); p("tpl", html_template_content(html_element(d, "template"))); p("tpl on mix", html_template_content(mix))
p("root", html_root(d)); p("root of ns", html_root(html_element(d, "p"))); p("root empty ns", html_root(div[0])); p("document", class(html_document(div))); p("document id", identical(html_document(div), d)); p("parent of root", html_parent(html_root(d))); p("parent of doc", html_parent(d)); p("children doc", html_children(d, FALSE))
p("doc vs root: elements", identical(html_elements(d, "p"), html_elements(html_root(d), "p")))
p("html self match", list(length(html_elements(d, "html")), length(html_elements(html_root(d), "html")), html_matches(html_root(d), "html"), html_matches(d, "html")))
p("element vs elements", list(html_element(mix, "b"), html_elements(mix, "b"), html_elements(mix[0], "b"), html_element(mix[0], "b")))
p("matches", html_matches(mix, "p")); p("filter", html_filter(mix, "p, div")); p("filter doc", html_filter(d, "p")); p("closest", html_closest(c(html_element(d, "b"), div[NA_integer_], html_element(d, "b")), "div")); p("closest self", html_closest(div, "div"))
for (cv in list("", " ", NA_character_, c("p","b"), 1, NULL, factor("p"), "p,", "P", "p:hover", "*", "#a.x", "[data-n='7']", "[DATA-N=\"8\"]", "p\n,\tb", "é")) { cat("css", deparse(cv)[1], ": "); print(tr(length(html_elements(d, cv)))) }
p("serialize", html_serialize(mix)); p("inner", html_serialize(mix, outer = FALSE)); p("pretty", html_serialize(div, pretty = TRUE)); p("serialize doc", html_serialize(d)); p("as.character doc", tr(as.character(d)))
p("serialize doc == root route", identical(html_serialize(d, outer = FALSE), html_serialize(d)))
p("markdown", html_markdown(mix)); p("markdown doc", html_markdown(d))
m <- html_parse("<p><a href='rel?a=1'>l</a> <img src='i.png' alt=A> <a href='http://abs/'>abs</a><a href='x y'>bad</a></p>")
p("markdown nobase", html_markdown(m)); p("markdown on a", html_markdown(html_elements(m, "a, img")))
m2 <- html_parse("<base href='http://b/d/'><p><a href='rel'>l</a><img src=i.png></p>", base_url = "http://ignored/")
p("markdown base", html_markdown(m2)); p("markdown NA/dup", html_markdown(html_elements(m2, "p")[c(1, NA, 1)]))
# fragment
for (cx in list("div", "DIV", "table", "tr", "select", "title", "script", "svg", "math", "nosuch", "", NA_character_, c("a","b"), 1, NULL, " div", "body", "html", "template", "textarea", "plaintext")) { cat("context", deparse(cx)[1], ": "); print(tr({f <- html_fragment("<td>x</td><p>y", context = cx); paste(html_info(f)$context, "|", paste(html_serialize(f), collapse = ""))})) }
f <- html_fragment("<p>a</p><p>b</p>"); p("frag print", print(f)); p("frag root", html_root(f)); p("frag children", html_children(f)); p("frag info", unclass(html_info(f))[c("type","context","encoding","encoding_source","base_url")])
p("frag dots", list(tr(html_fragment("<p>", "div", "latin1")), tr(html_fragment("<p>", enc = "UTF-8")), tr(html_fragment("<p>", comments = NULL, limits = NULL, encoding = NULL, base_url = NULL)), tr(html_fragment("<p>", comments = NA)), tr(html_fragment("<p>", base_url = 1)), tr(html_fragment("<p>", limits = html_limits(max_input = 1)))))
p("frag raw meta", html_info(html_fragment(c(charToRaw("<meta charset=latin1><p>"), as.raw(0xe9))))$encoding)
p("frag comments", html_serialize(html_fragment("<!--c--><p>a", comments = FALSE)))
p("parse comments", list(html_serialize(html_parse("<!--c--><p>a<!--d-->", comments = FALSE)), tr(html_parse("<p>", comments = "no")), tr(html_parse("<p>", comments = 0))))
